import React, { useState, useEffect, useMemo } from 'react';
import { getPendingOwnerProfiles, getOwnerProfileById, verifyOwnerProfile } from '../../api/listingService';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '../ui/card';
import { Button } from '../ui/button';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '../ui/table';
import { Badge } from '../ui/badge';
import { Label } from '../ui/label';
import { Textarea } from '../ui/textarea';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from '../ui/dialog';
import { Separator } from '../ui/separator';
import { AlertTriangle, CheckCircle, Eye, XCircle, User, CreditCard, ShieldCheck, Utensils, ImageIcon } from 'lucide-react';
import { toast } from "sonner";
import Pagination from '../ui/Pagination';

const SERVICE_TYPE_LABELS = {
    room: 'Room Provider',
    mess: 'Mess Provider',
    both: 'Room & Mess',
    unknown: 'Unknown'
};

const ViewDocumentButton = ({ file, index, label }) => {
    const [open, setOpen] = useState(false);

    return (
        <>
            <Button
                variant="outline"
                size="sm"
                onClick={() => setOpen(true)}
                className="flex items-center gap-2"
            >
                <ImageIcon className="h-3 w-3 text-muted-foreground" />
                {file.name || `${label} ${index + 1}`}
            </Button>
            <Dialog open={open} onOpenChange={setOpen}>
                <DialogContent className="sm:max-w-2xl max-h-[90vh] overflow-y-auto">
                    <DialogHeader>
                        <DialogTitle>{file.name || `${label} ${index + 1}`}</DialogTitle>
                        <DialogDescription>{label}</DialogDescription>
                    </DialogHeader>
                    <div className="flex justify-center items-center bg-muted rounded-lg p-4 min-h-[300px]">
                        <img
                            src={file.url}
                            alt={file.name || `${label} ${index + 1}`}
                            className="max-w-full max-h-[70vh] object-contain rounded-lg"
                            onError={(e) => {
                                e.target.onerror = null;
                                e.target.src = '';
                                e.target.alt = 'Failed to load document';
                            }}
                        />
                    </div>
                </DialogContent>
            </Dialog>
        </>
    );
};

const DetailField = ({ label, children, className = '' }) => (
    <div className={className}>
        <Label className="text-muted-foreground text-xs">{label}</Label>
        <div className="mt-0.5 text-sm font-medium text-foreground">{children}</div>
    </div>
);

const OwnerDetailModal = ({ profile, open, onOpenChange, onApprove, onReject }) => {
    const [loading, setLoading] = useState(false);
    const [detailData, setDetailData] = useState(null);

    useEffect(() => {
        if (open && profile?.ownerId) {
            const fetchDetails = async () => {
                setLoading(true);
                try {
                    const data = await getOwnerProfileById(profile.ownerId);
                    setDetailData(data);
                } catch (error) {
                    toast.error('Failed to load owner profile details');
                    setDetailData(null);
                } finally {
                    setLoading(false);
                }
            };
            fetchDetails();
        }
    }, [open, profile]);

    const personal = detailData?.personal || profile?.personal || {};
    const documents = detailData?.documents || profile?.documents || {};
    const identity = documents.identity || {};
    const policeVerification = documents.policeVerification || {};
    const fssai = documents.fssai || {};
    const payment = detailData?.payment || profile?.payment || {};
    const serviceType = detailData?.serviceType || profile?.serviceType || 'unknown';

    const maskedAccount = payment.accountNumber
        ? `•••• •••• ${String(payment.accountNumber).slice(-4)}`
        : 'N/A';

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-4xl max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2">
                        <User className="h-5 w-5 text-primary" />
                        Owner Profile Review
                    </DialogTitle>
                    <DialogDescription>
                        Review all details and documents before approving or rejecting this owner profile.
                    </DialogDescription>
                </DialogHeader>

                {loading ? (
                    <div className="flex justify-center py-12">
                        <div className="space-y-4 w-full">
                            <div className="h-6 w-32 bg-gray-200 rounded animate-pulse"></div>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                {[1, 2, 3, 4, 5, 6].map(i => (
                                    <div key={i} className="h-16 bg-gray-100 rounded-lg animate-pulse"></div>
                                ))}
                            </div>
                        </div>
                    </div>
                ) : (
                    <div className="space-y-4 mt-2">
                        {/* Personal Details */}
                        <Card className="border-l-4 border-l-[#5D8C68]">
                            <CardHeader className="pb-3">
                                <CardTitle className="text-base flex items-center gap-2">
                                    <User className="h-4 w-4 text-primary" />
                                    Personal Details
                                </CardTitle>
                            </CardHeader>
                            <CardContent>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <DetailField label="Full Name">{personal.firstName || ''} {personal.lastName || ''}</DetailField>
                                    <DetailField label="Email">{personal.email || profile?.email || 'N/A'}</DetailField>
                                    <DetailField label="Phone">{personal.phone || profile?.phone || 'N/A'}</DetailField>
                                    {personal.whatsapp && (
                                        <DetailField label="WhatsApp">{personal.whatsapp}</DetailField>
                                    )}
                                    <DetailField label="Gender">
                                        <span className="capitalize">{personal.gender || 'N/A'}</span>
                                    </DetailField>
                                    <div>
                                        <Label className="text-muted-foreground text-xs">Service Type</Label>
                                        <div className="mt-0.5">
                                            <Badge variant="secondary">{SERVICE_TYPE_LABELS[serviceType] || serviceType}</Badge>
                                        </div>
                                    </div>
                                    {personal.address && (
                                        <DetailField label="Address" className="md:col-span-2">{personal.address}</DetailField>
                                    )}
                                    {personal.bio && (
                                        <DetailField label="Bio" className="md:col-span-2">{personal.bio}</DetailField>
                                    )}
                                </div>
                            </CardContent>
                        </Card>

                        {/* Identity Verification */}
                        <Card className="border-l-4 border-l-blue-500">
                            <CardHeader className="pb-3">
                                <CardTitle className="text-base flex items-center gap-2">
                                    <ShieldCheck className="h-4 w-4 text-blue-500" />
                                    Identity Verification
                                </CardTitle>
                            </CardHeader>
                            <CardContent>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <DetailField label="ID Proof Type">
                                        <span className="capitalize">{identity.idProofType || 'N/A'}</span>
                                    </DetailField>
                                    <DetailField label="ID Number">{identity.idNumber || 'N/A'}</DetailField>
                                    <div className="md:col-span-2">
                                        <Label className="text-muted-foreground text-xs">Uploaded Documents</Label>
                                        <div className="flex flex-wrap gap-2 mt-1">
                                            {identity.uploadedFiles?.length > 0 ? (
                                                identity.uploadedFiles.map((file, index) => (
                                                    <ViewDocumentButton
                                                        key={index}
                                                        file={file}
                                                        index={index}
                                                        label="Identity Document"
                                                    />
                                                ))
                                            ) : (
                                                <span className="text-muted-foreground italic text-sm">No documents uploaded</span>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            </CardContent>
                        </Card>

                        {/* Police Verification (room or both) */}
                        {['room', 'both'].includes(serviceType) && (
                            <Card className="border-l-4 border-l-blue-500">
                                <CardHeader className="pb-3">
                                    <CardTitle className="text-base flex items-center gap-2">
                                        <ShieldCheck className="h-4 w-4 text-blue-500" />
                                        Police Verification
                                    </CardTitle>
                                </CardHeader>
                                <CardContent>
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                        <DetailField label="Status">
                                            <Badge variant={
                                                policeVerification.status === 'verified' ? 'default' :
                                                policeVerification.status === 'pending' ? 'secondary' : 'outline'
                                            }>
                                                {policeVerification.status === 'not_applied' ? 'Not Applied Yet' :
                                                 policeVerification.status === 'verified' ? 'Verified' :
                                                 policeVerification.status === 'pending' ? 'Pending' : 'N/A'}
                                            </Badge>
                                        </DetailField>
                                        <div>
                                            <Label className="text-muted-foreground text-xs">Certificate</Label>
                                            <div className="flex flex-wrap gap-2 mt-1">
                                                {policeVerification.certificateFiles?.length > 0 ? (
                                                    policeVerification.certificateFiles.map((file, index) => (
                                                        <ViewDocumentButton
                                                            key={index}
                                                            file={file}
                                                            index={index}
                                                            label="Police Verification Certificate"
                                                        />
                                                    ))
                                                ) : (
                                                    <span className="text-muted-foreground italic text-sm">No certificate uploaded</span>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                </CardContent>
                            </Card>
                        )}

                        {/* FSSAI Details (mess or both) */}
                        {['mess', 'both'].includes(serviceType) && (
                            <Card className="border-l-4 border-l-orange-500">
                                <CardHeader className="pb-3">
                                    <CardTitle className="text-base flex items-center gap-2">
                                        <Utensils className="h-4 w-4 text-orange-500" />
                                        FSSAI Details
                                    </CardTitle>
                                </CardHeader>
                                <CardContent>
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                        <DetailField label="License Number">{fssai.licenseNumber || 'N/A'}</DetailField>
                                        <div>
                                            <Label className="text-muted-foreground text-xs">Certificate</Label>
                                            <div className="flex flex-wrap gap-2 mt-1">
                                                {fssai.certificateFiles?.length > 0 ? (
                                                    fssai.certificateFiles.map((file, index) => (
                                                        <ViewDocumentButton
                                                            key={index}
                                                            file={file}
                                                            index={index}
                                                            label="FSSAI Certificate"
                                                        />
                                                    ))
                                                ) : (
                                                    <span className="text-muted-foreground italic text-sm">No certificate uploaded</span>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                </CardContent>
                            </Card>
                        )}

                        {/* Payment Details */}
                        <Card className="border-l-4 border-l-indigo-500">
                            <CardHeader className="pb-3">
                                <CardTitle className="text-base flex items-center gap-2">
                                    <CreditCard className="h-4 w-4 text-indigo-500" />
                                    Payment Details
                                </CardTitle>
                            </CardHeader>
                            <CardContent>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <DetailField label="Account Holder Name">{payment.accountHolderName || 'N/A'}</DetailField>
                                    <DetailField label="Account Number">{maskedAccount}</DetailField>
                                    <DetailField label="IFSC Code">{payment.ifscCode || 'N/A'}</DetailField>
                                    <DetailField label="UPI ID">{payment.upiId || 'N/A'}</DetailField>
                                </div>
                            </CardContent>
                        </Card>

                        {/* Action Buttons */}
                        <Separator />
                        <div className="flex justify-end gap-3 pt-2">
                            <Button
                                variant="outline"
                                onClick={() => onOpenChange(false)}
                            >
                                Cancel
                            </Button>
                            <Button
                                variant="destructive"
                                onClick={() => {
                                    onOpenChange(false);
                                    onReject(profile);
                                }}
                            >
                                <XCircle className="h-4 w-4 mr-1" />
                                Reject
                            </Button>
                            <Button
                                className="bg-[#5D8C68] hover:bg-[#4A6F57]"
                                onClick={() => {
                                    onOpenChange(false);
                                    onApprove(profile.ownerId);
                                }}
                            >
                                <CheckCircle className="h-4 w-4 mr-1" />
                                Approve
                            </Button>
                        </div>
                    </div>
                )}
            </DialogContent>
        </Dialog>
    );
};

const RejectReasonDialog = ({ open, onOpenChange, onConfirm, ownerName }) => {
    const [reason, setReason] = useState('');
    const [loading, setLoading] = useState(false);

    const handleConfirm = async () => {
        if (!reason.trim()) {
            toast.error('Please provide a reason for rejection.');
            return;
        }
        setLoading(true);
        await onConfirm(reason.trim());
        setReason('');
        setLoading(false);
    };

    return (
        <Dialog open={open} onOpenChange={(isOpen) => {
            if (!isOpen) setReason('');
            onOpenChange(isOpen);
        }}>
            <DialogContent className="sm:max-w-md">
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2 text-destructive">
                        <XCircle className="h-5 w-5" />
                        Reject Owner Profile
                    </DialogTitle>
                    <DialogDescription>
                        Provide a reason for rejecting {ownerName}'s profile. This will be visible to the owner.
                    </DialogDescription>
                </DialogHeader>
                <div className="py-4">
                    <Label htmlFor="reject-reason" className="text-sm font-medium">Rejection Reason</Label>
                    <Textarea
                        id="reject-reason"
                        value={reason}
                        onChange={(e) => setReason(e.target.value)}
                        placeholder="Enter rejection reason (e.g., 'ID document is unclear. Please upload a clearer image.')"
                        rows={4}
                        className="resize-none mt-1.5"
                        maxLength={500}
                    />
                    <p className="text-xs text-muted-foreground mt-1 text-right">{reason.length}/500</p>
                </div>
                <DialogFooter className="gap-2">
                    <Button variant="outline" onClick={() => { setReason(''); onOpenChange(false); }}>
                        Cancel
                    </Button>
                    <Button
                        variant="destructive"
                        onClick={handleConfirm}
                        disabled={loading || !reason.trim()}
                    >
                        {loading ? 'Rejecting...' : 'Confirm Rejection'}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
};

const ApproveOwnerProfiles = () => {
    const [profiles, setProfiles] = useState([]);
    const [loading, setLoading] = useState(true);
    const [message, setMessage] = useState('');
    const [currentPage, setCurrentPage] = useState(1);
    const itemsPerPage = 8;

    const [selectedProfile, setSelectedProfile] = useState(null);
    const [detailModalOpen, setDetailModalOpen] = useState(false);

    const [rejectProfile, setRejectProfile] = useState(null);
    const [rejectDialogOpen, setRejectDialogOpen] = useState(false);

    const fetchPendingProfiles = async () => {
        try {
            setLoading(true);
            const allPending = await getPendingOwnerProfiles();

            const ownerProfiles = allPending.filter(item => {
                const isOwner = item.serviceType || item.documents;
                return isOwner;
            });

            const finalPendingList = ownerProfiles.map(item => ({
                ...item,
                ownerId: item.userInfo?.userId || item.user_id || item.id,
                firstName: item.userInfo?.firstName || item.personal?.firstName || '',
                lastName: item.userInfo?.lastName || item.personal?.lastName || '',
                email: item.userInfo?.email || item.personal?.email || '',
                phone: item.userInfo?.phone || item.personal?.phone || '',
                serviceType: item.serviceType || 'unknown',
                role: item.userInfo?.role || ''
            }));

            setProfiles(finalPendingList);
        } catch (error) {
            console.error(error);
            setMessage('Failed to fetch owner profiles.');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchPendingProfiles();
    }, []);

    const handleApprove = async (ownerId) => {
        try {
            const verificationData = {
                action: 'approved',
                notes: 'Profile approved by admin'
            };
            await verifyOwnerProfile(ownerId, verificationData);
            toast.success('Owner profile has been approved.');
            fetchPendingProfiles();
        } catch (error) {
            toast.error('Failed to approve profile.');
        }
    };

    const handleRejectClick = (profile) => {
        setRejectProfile(profile);
        setRejectDialogOpen(true);
    };

    const handleRejectConfirm = async (reason) => {
        try {
            const verificationData = {
                action: 'rejected',
                notes: reason
            };
            await verifyOwnerProfile(rejectProfile.ownerId, verificationData);
            toast.success('Owner profile has been rejected.');
            setRejectDialogOpen(false);
            setRejectProfile(null);
            fetchPendingProfiles();
        } catch (error) {
            toast.error('Failed to reject profile.');
        }
    };

    const handleViewDetails = (profile) => {
        setSelectedProfile(profile);
        setDetailModalOpen(true);
    };

    const paginatedProfiles = useMemo(() => {
        const startIndex = (currentPage - 1) * itemsPerPage;
        return profiles.slice(startIndex, startIndex + itemsPerPage);
    }, [profiles, currentPage]);

    const handlePageChange = (page) => {
        setCurrentPage(page);
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    if (loading) {
        return (
            <div className="container mx-auto px-4 py-8">
                <div className="bg-white rounded-xl border-2 border-gray-200 p-6">
                    <div className="h-8 w-48 bg-gray-200 rounded animate-pulse mb-2"></div>
                    <div className="h-5 w-64 bg-gray-200 rounded animate-pulse mb-6"></div>
                    <div className="h-10 w-full bg-gray-200 rounded animate-pulse mb-6"></div>
                    <div className="space-y-3">
                        {[1, 2, 3, 4, 5, 6].map(i => (
                            <div key={i} className="h-20 w-full bg-gray-100 rounded-lg flex items-center px-4 animate-pulse">
                                <div className="w-16 h-16 bg-gray-200 rounded-full mr-4"></div>
                                <div className="flex-1">
                                    <div className="h-5 w-40 bg-gray-200 rounded mb-2"></div>
                                    <div className="h-4 w-56 bg-gray-200 rounded mb-2"></div>
                                    <div className="h-4 w-32 bg-gray-200 rounded"></div>
                                </div>
                                <div className="flex gap-2 ml-auto">
                                    <div className="h-9 w-24 bg-gray-200 rounded"></div>
                                    <div className="h-9 w-20 bg-gray-200 rounded"></div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="container mx-auto px-4 py-8">
            <Card className="border-2 border-border">
                <CardHeader>
                    <CardTitle className="flex items-center gap-2 text-2xl">
                        <AlertTriangle className="h-6 w-6 text-amber-600" />
                        Verify Owner Profiles
                    </CardTitle>
                    <CardDescription>
                        Review and verify owner profile completion requests. Click "View Details" to review documents before approving.
                    </CardDescription>
                </CardHeader>
                <CardContent>
                    {message && (
                        <Card className="border-destructive mb-4">
                            <CardContent className="py-3">
                                <p className="text-destructive text-sm">{message}</p>
                            </CardContent>
                        </Card>
                    )}
                    <Table>
                        <TableHeader>
                            <TableRow>
                                <TableHead>Owner Name</TableHead>
                                <TableHead>Email</TableHead>
                                <TableHead>Phone</TableHead>
                                <TableHead>Service Type</TableHead>
                                <TableHead>Status</TableHead>
                                <TableHead>Actions</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {paginatedProfiles.length > 0 ? paginatedProfiles.map(profile => (
                                <TableRow key={profile.ownerId}>
                                    <TableCell className="font-medium">
                                        {profile.firstName} {profile.lastName}
                                    </TableCell>
                                    <TableCell className="text-muted-foreground">
                                        {profile.email}
                                    </TableCell>
                                    <TableCell className="text-muted-foreground">
                                        {profile.phone || '-'}
                                    </TableCell>
                                    <TableCell>
                                        <Badge variant="secondary">
                                            {SERVICE_TYPE_LABELS[profile.serviceType] || profile.serviceType}
                                        </Badge>
                                    </TableCell>
                                    <TableCell>
                                        <Badge variant="outline" className="border-amber-500 text-amber-600 capitalize">
                                            pending
                                        </Badge>
                                    </TableCell>
                                    <TableCell>
                                        <div className="flex items-center gap-2">
                                            <Button
                                                variant="outline"
                                                size="sm"
                                                onClick={() => handleViewDetails(profile)}
                                            >
                                                <Eye className="h-4 w-4 mr-1" />
                                                View Details
                                            </Button>
                                            <Button
                                                size="sm"
                                                className="bg-[#5D8C68] hover:bg-[#4A6F57]"
                                                onClick={() => handleApprove(profile.ownerId)}
                                            >
                                                <CheckCircle className="h-4 w-4 mr-1" />
                                                Approve
                                            </Button>
                                            <Button
                                                variant="destructive"
                                                size="sm"
                                                onClick={() => handleRejectClick(profile)}
                                            >
                                                <XCircle className="h-4 w-4 mr-1" />
                                                Reject
                                            </Button>
                                        </div>
                                    </TableCell>
                                </TableRow>
                            )) : (
                                <TableRow>
                                    <TableCell colSpan="6" className="text-center py-8">
                                        <div className="flex flex-col items-center justify-center">
                                            <CheckCircle className="h-8 w-8 text-muted-foreground mb-2" />
                                            <p className="text-muted-foreground">No pending owner profiles to review</p>
                                        </div>
                                    </TableCell>
                                </TableRow>
                            )}
                        </TableBody>
                    </Table>
                    <Pagination
                        currentPage={currentPage}
                        totalItems={profiles.length}
                        itemsPerPage={itemsPerPage}
                        onPageChange={handlePageChange}
                    />
                </CardContent>
            </Card>

            <OwnerDetailModal
                profile={selectedProfile}
                open={detailModalOpen}
                onOpenChange={setDetailModalOpen}
                onApprove={handleApprove}
                onReject={handleRejectClick}
            />

            <RejectReasonDialog
                open={rejectDialogOpen}
                onOpenChange={setRejectDialogOpen}
                onConfirm={handleRejectConfirm}
                ownerName={rejectProfile ? `${rejectProfile.firstName} ${rejectProfile.lastName}` : ''}
            />
        </div>
    );
};

export default ApproveOwnerProfiles;
